n = int(input())
cs = {}
for i in range(n):
  a, c = map(int, input().split())
  if c in cs:
    cs[c].append(a)
  else:
    cs[c] = [a]

best_color = -1
max_min_deliciousness = -1
for k in cs:
  m = min(cs[k])
  if m > max_min_deliciousness:
    best_color = k
    max_min_deliciousness = m
  elif m == max_min_deliciousness and k < best_color:
    best_color = k

print(best_color)
